import java.io.*;import java.util.*;public class TestClass {static class Element implements Comparable<Element> {int val, idx;Element(int val, int idx) {this.val = val;this.idx = idx;}public int compareTo(Element other) {if (this.val != other.val) return Integer.compare(this.val, other.val);return Integer.compare(this.idx, other.idx);}}public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));int T = Integer.parseInt(br.readLine().trim());while (T-- > 0) {int N = Integer.parseInt(br.readLine().trim());StringTokenizer st = new StringTokenizer(br.readLine());Element[] arr = new Element[N];for (int i = 0; i < N; i++) {arr[i] = new Element(Integer.parseInt(st.nextToken()), i + 1);}Arrays.sort(arr);long totalSub = 0;int count = N;int lastIdx = -1;for (int i = 0; i < N; i++) {long currentVal = arr[i].val - totalSub;if (currentVal < arr[i].idx) {count = N - i;lastIdx = arr[i].idx;break;}long numSteps = currentVal / arr[i].idx;totalSub += numSteps * arr[i].idx;if (arr[i].val - totalSub < arr[i].idx) {count = N - i;lastIdx = arr[i].idx;break;}}if (count == 1) {System.out.println("Ladia");} else {System.out.println("Kushagra");}}}}